import json
from pathlib import Path
selectors = {'missions': ['CANADA-STANDALONE-DATA-QA-BUYER', 'CATALOGUE-COMMISSIONED-REVIEW-LIVE-TEST', 'WELFARE-LIVE-DEMAND', 'WELFARE-SITE-RETIRE', 'TEXT-CSV-INTAKE-EXPERIMENT'], 'reviews': ['b5192231bdfa03f011ea45273891c67b883b7c0a4f4d2bef75f7b22e684aa711']}
for collection, wanted in selectors.items():
    files = sorted(Path('world/pages').glob(collection + '-*.json'))
    def records(value):
        if isinstance(value, list):
            for item in value:
                yield from records(item)
        elif isinstance(value, dict):
            if 'mission_id' in value or 'digest' in value:
                yield value
            else:
                for item in value.values():
                    yield from records(item)
    matches = []
    fields = ('mission_id', 'status', 'agent_id', 'evidence', 'subject', 'digest', 'verdict', 'host_provider', 'host_turn', 'seq')
    for path in files:
        for item in records(json.loads(path.read_text())):
            if item.get('mission_id') in wanted or item.get('digest') in wanted:
                matches.append({key: item[key] for key in fields if key in item})
    print(json.dumps(dict(collection=collection, pages_read=len(files), matches=matches)))
